#!/bin/bash
# Generated by OrchestKit Claude Plugin
# Created: 2026-08-21

# Unit test for src/skills/doctor/scripts/check-sandbox-violations.sh
#
# The unified-log query is environment-dependent (macOS only, and the log CLI
# refuses sandboxed callers), so these tests assert the CONTRACT rather than a
# fixed environment: argument validation, the platform gate, exit-code/status
# coherence in --json mode, and above all the fail-closed rule: an unobservable
# query must never present as a zero-violation pass.

set -euo pipefail

SCRIPT_DIR="$(cd "$(dirname "$0")" && pwd)"
REPO_ROOT="$(cd "$SCRIPT_DIR/../.." && pwd)"
CHECK="$REPO_ROOT/src/skills/doctor/scripts/check-sandbox-violations.sh"

if [[ ! -x "$CHECK" ]]; then
    echo "FAIL: $CHECK not found or not executable" >&2
    exit 1
fi

PASS=0
FAIL=0

assert_exit() {
    local name="$1" expected="$2" actual="$3"
    if [[ "$expected" -eq "$actual" ]]; then
        echo "  ✓ $name (exit=$actual)"
        PASS=$((PASS + 1))
    else
        echo "  ✗ $name (expected exit=$expected, got $actual)"
        FAIL=$((FAIL + 1))
    fi
}

assert_contains() {
    local name="$1" needle="$2" haystack="$3"
    if [[ "$haystack" == *"$needle"* ]]; then
        echo "  ✓ $name"
        PASS=$((PASS + 1))
    else
        echo "  ✗ $name (missing: $needle)"
        echo "      output: $haystack"
        FAIL=$((FAIL + 1))
    fi
}

assert_not_contains() {
    local name="$1" needle="$2" haystack="$3"
    if [[ "$haystack" != *"$needle"* ]]; then
        echo "  ✓ $name"
        PASS=$((PASS + 1))
    else
        echo "  ✗ $name (should not contain: $needle)"
        FAIL=$((FAIL + 1))
    fi
}

echo "Test 1: malformed --window is a usage error (bounded queries only)"
RC=0
OUT="$("$CHECK" --window forever 2>&1)" || RC=$?
assert_exit "bad window exits 4" 4 "$RC"
assert_contains "bad window names the flag" "--window" "$OUT"

echo "Test 2: unknown flag is a usage error"
RC=0
"$CHECK" --no-such-flag >/dev/null 2>&1 || RC=$?
assert_exit "unknown flag exits 4" 4 "$RC"

echo "Test 3: --help exits 0"
RC=0
"$CHECK" --help >/dev/null 2>&1 || RC=$?
assert_exit "--help exits 0" 0 "$RC"

echo "Test 4: JSON status is coherent with the exit code"
RC=0
JSON="$("$CHECK" --window 1m --json 2>&1)" || RC=$?
case "$RC" in
    0) assert_contains "exit 0 means status ok"            '"status":"ok"'           "$JSON" ;;
    1) assert_contains "exit 1 means status violations"    '"status":"violations"'   "$JSON" ;;
    2) assert_contains "exit 2 means status unobservable"  '"status":"unobservable"' "$JSON" ;;
    3) assert_contains "exit 3 means status skipped"       '"status":"skipped"'      "$JSON" ;;
    *) echo "  ✗ unexpected exit code $RC"; echo "      output: $JSON"; FAIL=$((FAIL + 1)) ;;
esac

echo "Test 5: FAIL-CLOSED: no path may report an unobserved zero"
# unobservable and skipped must carry count:null, never count:0
if [[ "$JSON" == *'"status":"unobservable"'* || "$JSON" == *'"status":"skipped"'* ]]; then
    assert_contains "unobserved result has count:null" '"count":null' "$JSON"
    assert_not_contains "unobserved result never claims count:0" '"count":0' "$JSON"
else
    # observed result must carry a numeric count and a real status
    assert_not_contains "observed result never has count:null" '"count":null' "$JSON"
fi

echo "Test 6: table mode carries the honest-limits caveat or the denial, never a bare zero"
RC=0
TABLE="$("$CHECK" --window 1m 2>&1)" || RC=$?
case "$RC" in
    0) assert_contains "clean pass states the no-report caveat" "not proof" "$TABLE" ;;
    1) assert_contains "violations output shows top offenders" "Top (count / process / operation)" "$TABLE" ;;
    2) assert_contains "unobservable output forbids the zero reading" "Do NOT read this as zero violations" "$TABLE" ;;
    3) assert_contains "skip names the platform reason" "macOS-only" "$TABLE" ;;
    *) echo "  ✗ unexpected exit code $RC"; FAIL=$((FAIL + 1)) ;;
esac

echo ""
echo "Results: $PASS passed, $FAIL failed"
[[ "$FAIL" -eq 0 ]] || exit 1
exit 0
